private string HtmlEncodeText(string strText)
{
    if (strText == null || strText.Length == 0)
        return "&nbsp;";
    return strText.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
}

private string GetHtmlCellText(DataRow drw, string strField)
{
    if (drw == null || !drw.Table.Columns.Contains(strField))
        return "&nbsp;";
    if (drw[strField] == DBNull.Value)
        return "&nbsp;";
    string str = Convert.ToString(drw[strField]).Trim();
    if (str.Length < 1)
        return "&nbsp;";
    return HtmlEncodeText(str);
}

private string FormatHtmlMark(object objValue, string strFormat)
{
    if (objValue == null || objValue == DBNull.Value)
        return "&nbsp;";
    string str = Convert.ToString(objValue).Trim();
    if (str.Length < 1)
        return "&nbsp;";
    if (str == "-1" || str == "-1,0" || str == "-1.0")
        return "M";
    try
    {
        double dbl = Convert.ToDouble(objValue);
        if (dbl < 0)
            return "M";
        if (Math.Abs(dbl - 10) < 0.01)
            return "10";
        return string.Format("{0:" + strFormat + "}", dbl);
    }
    catch
    {
        return HtmlEncodeText(str);
    }
}

