private void ExportBangDiemToanKhoa_HTML()
{
    try
    {
        if (gvData.GetSelectedRows().Length < 1)
        {
            MessageManager.Warning("Vui lòng chọn sinh viên cần xuất!");
            return;
        }

        SIM_Student objStudentMarkSummary = new SIM_Student();
        StringBuilder sbAll = new StringBuilder();
        int intExported = 0;

        foreach (int i in gvData.GetSelectedRows())
        {
            DataRow drw = gvData.GetDataRow(i);
            DataTable dtbStudentMarkSummary = objStudentMarkSummary.SearchStudentMarkSummary(Convert.ToInt64(drw[SIM_Student.C_StudentID]));
            if (dtbStudentMarkSummary == null || dtbStudentMarkSummary.Rows.Count < 1)
                continue;

            DataTable dtbMarks = dtbStudentMarkSummary.Copy();
            dtbMarks.DefaultView.RowFilter = "SpecialType <>5 and SpecialType<>8";
            dtbMarks = dtbMarks.DefaultView.ToTable();
            if (dtbMarks.Rows.Count < 1)
                continue;

            sbAll.Append(BuildBangDiemToanKhoaPageHtml(dtbStudentMarkSummary, dtbMarks));
            intExported++;
        }

        if (intExported < 1)
        {
            MessageManager.Warning("Không có dữ liệu để xuất HTML!");
            return;
        }

        string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_ToanKhoa_TinChi.htm", "Bảng điểm toàn khóa");
        string strFileContent = strTemplate.Replace("{CONTENT}", sbAll.ToString());
        SaveAndOpenHtml("BangDiem_ToanKhoa_TinChi.htm", strFileContent);
    }
    catch
    {
        ErrorManager.Error("Dữ liệu chưa hợp lệ để xuất HTML!");
    }
}

