private void SplitSchoolHeaderText(string strFull, out string strSchool, out string strPlace)
{
    strPlace = "NAM ĐỊNH";
    strSchool = "TRƯỜNG TRUNG CẤP CÔNG NGHỆ SỐ 8";
    if (strFull == null || strFull.Length < 1)
        return;

    string str = strFull.Trim();
    string[] arrLines = str.Split(new char[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);
    if (arrLines.Length > 1)
    {
        strSchool = arrLines[0].Trim();
        strPlace = arrLines[arrLines.Length - 1].Trim();
        return;
    }

    string strUpper = str.ToUpper();
    int intIdx = strUpper.LastIndexOf("NAM ĐỊNH");
    if (intIdx >= 0)
    {
        strSchool = str.Substring(0, intIdx).Trim();
        strPlace = str.Substring(intIdx).Trim();
        if (strSchool.Length < 1)
            strSchool = str;
    }
    else
        strSchool = str;
}

