private bool IsBangDiemSubjectWithAsterisk(DataRow drw, string strSubjectName)
{
    if (drw != null && drw.Table.Columns.Contains("SpecialType") && drw["SpecialType"] != DBNull.Value)
    {
        try
        {
            int intSpecialType = Convert.ToInt32(drw["SpecialType"]);
            if (intSpecialType == SubjectSpecialType.GiaoDucQuocPhong
                || intSpecialType == SubjectSpecialType.GiaoDucTheChat)
                return true;
        }
        catch
        {
        }
    }

    if (strSubjectName == null || strSubjectName.Length < 1)
        return false;

    string strUpper = strSubjectName.ToUpper();
    if (strUpper.IndexOf("GIÁO DỤC QUỐC PHÒNG") >= 0 || strUpper.IndexOf("GIAO DUC QUOC PHONG") >= 0)
        return true;
    if (strUpper.IndexOf("GIÁO DỤC THỂ CHẤT") >= 0 || strUpper.IndexOf("GIAO DUC THE CHAT") >= 0)
        return true;
    return false;
}

private string GetBangDiemSubjectNameHtml(DataRow drw)
{
    string strName = "";
    if (drw != null && drw.Table.Columns.Contains("SubjectName") && drw["SubjectName"] != DBNull.Value)
        strName = Convert.ToString(drw["SubjectName"]).Trim();
    if (strName.Length < 1)
        return "&nbsp;";
    if (IsBangDiemSubjectWithAsterisk(drw, strName))
        strName = strName + "*";
    return HtmlEncodeText(strName);
}

